class sentimentdata(Dataset):
    def __init__(self , X,Y, max_len=53):
        self.X = X
        self.Y = Y
        self.max_len = max_len
    def __len__(self):
        return len(self.X)
    def __getitem__(self , index):
        x = self.X[index]
        y= self.Y[index]
        # Pad x to max_len
        if len(x) < self.max_len:
            padded_x = torch.zeros(self.max_len)
            padded_x[:len(x)] = x
            x = padded_x.long()
        elif len(x) > self.max_len:
            x = x[:self.max_len].long()
        else:
            x = x.long()
        # Convert y to one-hot encoding (2 classes)
        one_hot_y = torch.zeros(2)
        one_hot_y[y] = 1
        return x, one_hot_y.long()

